style.css:
@-moz-document domain("panopto.com"), regexp("https?://[^/]*\.panopto\.(com|eu)/.*") {
/* Invert the whole page into a dark theme */
  html {
    filter: invert(1) hue-rotate(180deg) !important;
    background: #fff !important; /* inverts to near-black */
  }

  /* Re-invert media so it looks normal */
  video,
  img,
  canvas,
  picture,
  iframe,
  svg image,
  [style*="background-image"],
  .thumbnail,
  .thumbnail-image,
  #primaryVideo,
  #videoContainer,
  .video-js,
  .player-container,
  #playerContainer {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* Slightly soften the result (pure black can feel harsh) */
  html {
    background-color: #f2f2f2 !important; /* inverts to ~#0d0d0d */
  }

  /* Scrollbars */
  ::-webkit-scrollbar { background: #ddd; }
  ::-webkit-scrollbar-thumb { background: #aaa; }
}
